function savedBase(){try{const s=localStorage.getItem('lx-analyst-api')||'';return safeBase(s);}catch{return '';}}
function safeBase(value){if(!value)return '';const u=new URL(value);if(!['http:','https:'].includes(u.protocol))throw new Error('请使用 HTTPS 或本机 HTTP 地址。');if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw new Error('远程分析 API 需要使用 HTTPS。');if(u.username||u.password||u.search||u.hash)throw new Error('API 地址不能含账号、密码、查询参数或片段。');return value.replace(/\/+$/,'').replace(/\/api\/v1$/,'');}
function saveBase(value){try{value?localStorage.setItem('lx-analyst-api',value):localStorage.removeItem('lx-analyst-api');}catch{}}
function api(path){return `${state.apiBase}${path}`;}
function meta(domain=domainID()){return state.catalog.domains?.find(d=>d.id===domain)||FALLBACK.domains.find(d=>d.id===domain)||{};}
function domainID(){return state.page==='growth'?'onboarding':state.page;}
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('visible'),3600);}
async function jsonFetch(path,{timeout=12000,signal,...options}={}){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);if(signal){if(signal.aborted)controller.abort();else signal.addEventListener('abort',()=>controller.abort(),{once:true});}try{const isAPI=typeof path==='string'&&path.startsWith(api('/api/'));const r=await fetch(path,{...options,signal:controller.signal,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(isAPI&&state.accessToken?{Authorization:`Bearer ${state.accessToken}`} : {}),...(options.headers||{})}});if(!r.ok){let message;try{const d=await r.json();message=typeof d.detail==='string'?d.detail:Array.isArray(d.detail)?d.detail.map(x=>`${x.loc?.at(-1)||'参数'}：${x.msg}`).join('；'):d.message;}catch{}throw new Error(message||`请求失败（HTTP ${r.status}）`);}return await r.json();}finally{clearTimeout(timer);}}
async function snapshot(id){if(state.snapshots[id])return state.snapshots[id];const data=await jsonFetch(new URL(`./demo/${id}.json`,import.meta.url),{timeout:8000});state.snapshots[id]=data;return data;}
function setConnection(){const n=document.querySelector('#connection-status');n.className=`connection-status ${state.online?'online':'offline'}`;n.innerHTML=`<i></i>${!state.ready?'读取运行状态':state.online?'分析 API 已连接':'计算回放'}`;n.title=state.online?'可以运行 Python 计算；模型模式以服务配置为准':'读取保存的计算结果，不重新执行模型或查询';}
async function connect(){state.ready=false;setConnection();try{const data=await jsonFetch(api('/api/v1/catalog'),{timeout:4500});if(!Array.isArray(data.domains))throw new Error('目录格式不正确');state.catalog=data;state.online=true;}catch{state.online=false;try{const data=await snapshot('catalog');state.catalog={...FALLBACK,...data,domains:[...arr(data.domains),...FALLBACK.domains.filter(f=>!arr(data.domains).some(d=>d.id===f.id))]};}catch{state.catalog=FALLBACK;}}state.ready=true;setConnection();render();}
function route(){const [raw,query]=location.hash.slice(1).split('?');return {page:Object.hasOwn(PAGES,raw)?raw:'overview',params:new URLSearchParams(query||'')};}
function render(){const r=route();state.page=r.page;state.controller?.abort();state.version++;state.result=null;document.title=state.page==='overview'?'刘希 · AI 数据分析作品集':`${PAGES[state.page]} · 刘希`;document.querySelector('#breadcrumb-current').textContent=PAGES[state.page];document.querySelectorAll('.nav-link').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});closeNav();if(state.page==='overview')renderOverview();else if(WORKBENCH.includes(state.page))renderWorkbench(r.params);else if(state.page==='cases')renderCases();else if(state.page==='evaluation')renderEvaluation();else if(state.page==='monitoring')renderMonitoring();else renderAbout();hydrateIcons(main);}
function block(title,body,extra=''){return `<section class="result-section ${extra}"><div class="result-section-head"><h3>${e(title)}</h3></div><div class="result-section-body">${body}</div></section>`;}
