function scenarioOptions(domain){const defaults=SCENARIOS[domain]||[];const declared=meta(domain).metadata?.scenarios||meta(domain).scenarios;if(!declared)return defaults;const entries=Array.isArray(declared)?declared:Object.entries(declared).map(([id,v])=>({id,...(typeof v==='object'?v:{label:v})}));return defaults.map(s=>{const detail=entries.find(x=>(x.id||x.scenario||x.value)===s.id);return {...s,...detail,label:s.label,description:detail?.label||s.note};});}
