function renderWorkbench(params){const d=domainID(),m=meta(d),def=m.default_request||{},scenarios=scenarioOptions(d);state.scenario=scenarios.some(s=>s.id===params.get('scenario'))?params.get('scenario'):def.filters?.scenario||scenarios[0]?.id;const s=scenarioEntry();const descriptions={onboarding:['GROWTH WORKBENCH','新用户承接与留存','从质量检查、变化拆解到漏斗证据，形成一份有依据的增长决策。'],experiments:['EXPERIMENT REVIEW','实验评审与决策','先确认结果可用，再评估业务效应、体验围栏和后续动作。'],repurchase:['REPURCHASE OPERATIONS','复购运营与预算','在清晰的观察时点与预算约束下，选择运营候选并规划随机验证。']};const [eyebrow,title,description]=descriptions[d];
main.innerHTML=`${heading(eyebrow,title,description,`<a href="#cases" class="text-link">案例背景 ${icon('book')}</a>`)}<div class="scenario-selector" role="group" aria-label="选择分析场景">${scenarios.map((sc,i)=>`<button type="button" class="scenario-button ${sc.id===state.scenario?'active':''}" data-scenario="${e(sc.id)}" aria-pressed="${sc.id===state.scenario}"><span>${String(i+1).padStart(2,'0')}</span>${e(sc.label)}${sc.short?`<small>${e(sc.short)}</small>`:''}</button>`).join('')}</div>
<div class="workbench-mode"><span class="mode-dot ${state.online?'connected':''}"></span><strong>${state.online?'已连接分析服务':'已保存计算回放'}</strong><span>${state.online?'参数提交到 Python API；运行方式可在下方选择。':'切换场景可查看对应计算结果、SQL 与报告。'}</span>${!state.online?'<button type="button" class="text-link" id="connect-inline">连接 API ↗</button>':''}</div>
<div class="workbench-layout"><aside class="query-panel"><form id="query-form"><div class="query-panel-heading"><span class="eyebrow">ANALYSIS BRIEF</span><span>${icon('terminal')}</span></div><label class="field-label" for="question">${state.online?'业务问题':'本次分析问题'}</label><textarea id="question" maxlength="1500" rows="5" ${state.online?'':'readonly'}>${e(s?.question||def.question||'分析所选业务场景')}</textarea><p id="scenario-note" class="field-help">${e(s?.note||'基于实验注册与数据质量，检查效应、围栏和决策条件。')}</p>
${state.online?`<div class="mode-toggle" role="group" aria-label="执行方式"><button type="button" data-mode="demo" class="${state.mode==='demo'?'active':''}" aria-pressed="${state.mode==='demo'}">Python 计算</button><button type="button" data-mode="live" class="${state.mode==='live'?'active':''}" aria-pressed="${state.mode==='live'}" ${state.catalog.model?.configured?'':'disabled'}>AI + 工具</button></div><p id="mode-help" class="field-help">${state.mode==='live'?'模型规划与解释，工具负责取数与统计。':'确定性业务计算；当前方式不调用模型。'}</p>`:''}
<label class="field-label" for="task">分析交付</label><select id="task" ${state.online?'':'disabled'}>${(d==='onboarding'?[['diagnose','完整诊断'],['quality','数据质量'],['funnel','有序漏斗'],['report','增长报告']]:d==='experiments'?[['experiment','实验评审'],['report','实验报告']]:[['segment','分群与留出计划'],['diagnose','复购诊断'],['report','复购报告']]).map(([id,l])=>`<option value="${id}" ${id===def.task?'selected':''}>${l}</option>`).join('')}</select>
<details class="query-parameters" open><summary>指标与分析范围 ${icon('chevron')}</summary>${d==='onboarding'?`<label class="field-label" for="filter-metric">结果指标</label><select id="filter-metric" ${state.online?'':'disabled'}>${[['new_user_retention_d7','精确 D7 留存'],['new_user_retention_d1','精确 D1 留存'],['return_within_days_1_7','次 1—7 日任意回访'],['activated_24h','注册后 24h 激活']].map(([id,t])=>`<option value="${id}" ${id===(def.filters?.metric||'new_user_retention_d7')?'selected':''}>${t}</option>`).join('')}</select>`:''}<div class="date-grid"><div><label for="start">分析开始</label><input type="date" id="start" value="${e(def.start||'')}" ${state.online?'':'disabled'}></div><div><label for="end">分析结束</label><input type="date" id="end" value="${e(def.end||'')}" ${state.online?'':'disabled'}></div>${d==='onboarding'?`<div><label for="compare-start">对比开始</label><input type="date" id="compare-start" value="${e(def.compare_start||'')}" ${state.online?'':'disabled'}></div><div><label for="compare-end">对比结束</label><input type="date" id="compare-end" value="${e(def.compare_end||'')}" ${state.online?'':'disabled'}></div>`:''}</div>${filterFields(d,m)}<p class="field-help">${e(m.data_source||'合成演示数据')}${m.data_range?`<br>${e(m.data_range.start)} — ${e(m.data_range.end)}`:''}</p></details><button class="button button-primary button-block query-submit" type="submit" id="run-analysis" ${state.ready?'':'disabled'}>${icon(state.online?'play':'refresh')}<span>${state.online?'运行分析':'重新载入回放'}</span></button><button class="button button-quiet button-block" type="button" id="cancel-analysis" hidden>取消本次请求</button></form><div class="query-panel-foot">${icon('lock')}只读取数 · 证据留存 · 报告可下载</div></aside><section class="workspace-results" aria-label="分析结果" aria-live="polite"><div id="analysis-result">${loading()}</div></section></div>`;
document.querySelector('#query-form').addEventListener('submit',submitAnalysis);document.querySelector('#connect-inline')?.addEventListener('click',openSettings);document.querySelectorAll('[data-scenario]').forEach(btn=>btn.addEventListener('click',()=>{location.hash=`${state.page}?scenario=${encodeURIComponent(btn.dataset.scenario)}`;}));document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{state.mode=btn.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});document.querySelector('#mode-help').textContent=state.mode==='live'?'模型规划与解释，工具负责取数与统计。':'确定性业务计算；当前方式不调用模型。';markChanged();}));document.querySelector('#query-form').addEventListener('input',markChanged);document.querySelector('#query-form').addEventListener('change',markChanged);document.querySelector('#cancel-analysis').addEventListener('click',()=>{state.controller?.abort();});if(d==='experiments'){const dateMeta=s?.default_request||s;document.querySelector('#start').value=dateMeta?.start||'';document.querySelector('#end').value=dateMeta?.end||'';}loadReplay();}
function filterFields(d,m){const disabled=state.online?'':'disabled';if(d==='experiments')return '';if(d==='repurchase')return `<div class="date-grid"><div><label for="filter-region">地区</label><select id="filter-region" ${disabled}><option value="">全部地区</option>${arr(m.filters?.region).filter(v=>v!=='all').map(v=>`<option value="${e(typeof v==='object'?v.value:v)}">${e(typeof v==='object'?v.label:v)}</option>`).join('')}</select></div><div><label for="filter-budget">计划预算（元）</label><input type="number" id="filter-budget" min="0" max="1000000" step="1" value="${e(m.default_request?.filters?.budget??200)}" ${disabled}></div></div>`;return `<div class="date-grid">${['channel','device','app_version'].map(key=>`<div><label for="filter-${key}">${label(key)}</label><select id="filter-${key}" ${disabled}><option value="">全部</option>${arr(m.filters?.[key]||FALLBACK.domains[0].filters[key]).map(v=>`<option value="${e(typeof v==='object'?v.value:v)}">${e(typeof v==='object'?v.label:({organic:'自然渠道',paid_search:'付费搜索',social:'社交渠道',referral:'推荐渠道',android:'Android',ios:'iOS',web:'Web'}[v]||v))}</option>`).join('')}</select></div>`).join('')}</div>`;}
function markChanged(){if(!state.online)return;const interrupted=state.busy;state.controller?.abort();state.version++;setBusy(false);if(interrupted){if(state.result)renderResult(state.result);else document.querySelector('#analysis-result').innerHTML=unavailable('参数已改变，请重新运行分析。');}if(state.result&&!document.querySelector('#result-stale')){const el=document.createElement('div');el.id='result-stale';el.className='notice notice-amber';el.innerHTML=`${icon('info')}<p>参数已改变。下方为上一次运行结果，重新运行后更新。</p>`;document.querySelector('#analysis-result').prepend(el);}}
async function loadReplay(){const v=state.version;try{const data=await snapshot(snapshotName());if(v!==state.version)return;state.result={...data,_replay:true};renderResult(state.result);if(!state.online&&data.request){const req=data.request,windowFields=requestWindow(data);document.querySelector('#question').value=req.question||scenarioEntry()?.question||'';document.querySelector('#task').value=req.task||meta().default_request?.task||'';for(const [k,id]of [['start','start'],['end','end'],['compare_start','compare-start'],['compare_end','compare-end']]){const el=document.getElementById(id);if(el)el.value=windowFields[k]||'';}for(const key of ['metric','channel','device','app_version','region','budget']){const el=document.getElementById(`filter-${key}`);if(el&&req.filters?.[key]!==undefined)el.value=req.filters[key];}}}catch(err){if(v===state.version)document.querySelector('#analysis-result').innerHTML=unavailable(state.online?'该场景未附预存回放。点击“运行分析”生成本次结果。':'该场景回放暂不可用。可连接分析 API 运行，或查看其他案例。');}}
function setBusy(busy){state.busy=busy;const btn=document.querySelector('#run-analysis');if(!btn)return;btn.disabled=busy||!state.ready;btn.innerHTML=busy?'<span class="spinner"></span>正在执行…':`${icon(state.online?'play':'refresh')}<span>${state.online?'运行分析':'重新载入回放'}</span>`;document.querySelector('#cancel-analysis').hidden=!busy;document.querySelector('.workspace-results').setAttribute('aria-busy',String(busy));}
async function submitAnalysis(event){event.preventDefault();if(!state.online){await loadReplay();toast('已重新读取保存的计算结果。');return;}const q=document.querySelector('#question').value.trim();if(!q){toast('请输入一个业务问题。');return;}const d=domainID(),body={domain:d,question:q,task:document.querySelector('#task').value,mode:state.mode,filters:{...(meta(d).default_request?.filters||{}),...(d!=='repurchase'?{scenario:state.scenario}:{})}};for(const [key,id]of [['start','start'],['end','end'],['compare_start','compare-start'],['compare_end','compare-end']]){const val=document.getElementById(id)?.value;if(val)body[key]=val;}for(const key of ['metric','channel','device','app_version','region','budget']){const el=document.getElementById(`filter-${key}`);if(!el)continue;if(el.value)body.filters[key]=key==='budget'?Number(el.value):el.value;else delete body.filters[key];}if(body.start&&body.end&&body.start>body.end){toast('分析开始日期不能晚于结束日期。');return;}if(body.compare_start&&body.compare_end&&body.compare_start>body.compare_end){toast('对比开始日期不能晚于结束日期。');return;}state.controller?.abort();state.controller=new AbortController();const v=++state.version;setBusy(true);document.querySelector('#analysis-result').innerHTML=loading(state.mode==='live'?'模型正在调用分析工具，结果完成后展示实际执行记录。':'正在执行 Python 计算与数据验证。');try{const data=await jsonFetch(api('/api/v1/analyze'),{method:'POST',body:JSON.stringify(body),signal:state.controller.signal,timeout:125000});if(v!==state.version)return;state.result=data;renderResult(data);}catch(err){if(v!==state.version)return;document.querySelector('#analysis-result').innerHTML=`<div class="error-panel"><div class="error-icon">${icon('alert')}</div><h2>本次分析未完成</h2><p>${e(err.name==='AbortError'?'请求已取消或超时。可以重新运行。':err.message)}</p><button type="button" id="retry-analysis" class="button button-secondary">重新运行 ${icon('refresh')}</button></div>`;document.querySelector('#retry-analysis').onclick=()=>document.querySelector('#query-form').requestSubmit();}finally{if(v===state.version)setBusy(false);}}
function renderResult(data){const mode=data._replay?'保存的计算回放':data.mode==='live'?'真实模型 + 工具调用':'Python 确定性计算';const panes=[['data','结果数据'],['evidence',`SQL 证据 · ${arr(data.evidence).length}`],['trace','执行记录'],['contract','指标口径']];document.querySelector('#analysis-result').innerHTML=`<div class="result-titlebar"><div><span class="eyebrow">ANALYSIS OUTPUT</span><h2>${e(data.title||'分析结果')}</h2><div class="result-meta">${badge(data.status||'completed')}<span>${e(mode)}</span>${data.run_id?`<code title="${e(data.run_id)}">#${e(data.run_id.slice(0,8))}</code>`:''}</div></div><div class="result-actions"><button type="button" class="icon-button" data-download="html" aria-label="下载 HTML 报告" title="下载 HTML 报告">${icon('download')}</button><button type="button" class="icon-button" data-download="md" aria-label="下载 Markdown 报告" title="下载 Markdown 报告">${icon('file')}</button><button type="button" class="icon-button" data-download="json" aria-label="下载完整 JSON 结果" title="下载完整 JSON 结果">${icon('code')}</button></div></div>${data._replay?'<p class="replay-note">该结果来自保存的合成数据计算；本次读取不重新执行模型或查询。</p>':''}${data.summary?`<p class="result-summary">${e(data.summary)}</p>`:''}${data.clarification?`<div class="suggestion-box"><h3>需要明确分析口径</h3><p>${e(data.clarification.question)}</p><div class="suggestion-options">${arr(data.clarification.options).map((o,i)=>`<button class="button button-secondary" data-clarify="${i}" type="button">${e(text(o))}</button>`).join('')}</div></div>`:''}${qualityHTML(data.data_quality)}${decisionHTML(data.decision)}${arr(data.kpis).length?`<div class="kpi-grid">${data.kpis.map(kpiHTML).join('')}</div>`:''}${data.checks?block('实验健康与决策检查',checksHTML(data.checks),'checks-section'):''}${funnelHTML(data.funnel)}${arr(data.charts).length?`<div class="charts-grid">${data.charts.map(c=>`<section class="result-section chart-section"><div class="result-section-head"><h3>${e(c.title)}</h3><span>${e(c.type||'CHART')}</span></div><div class="chart-wrap">${chartHTML(c)}</div></section>`).join('')}</div>`:''}${findingsHTML(data.findings)}${hypothesesHTML(data.hypotheses)}
<section class="result-section evidence-workspace"><div class="result-tabs" role="tablist" aria-label="计算结果详情">${panes.map(([id,t],i)=>`<button class="result-tab ${i===0?'active':''}" role="tab" aria-selected="${i===0}" aria-controls="pane-${id}" id="tab-${id}" data-tab="${id}" tabindex="${i===0?0:-1}">${t}</button>`).join('')}</div><div class="tab-pane" id="pane-data" role="tabpanel" aria-labelledby="tab-data">${arr(data.tables).length?data.tables.map(t=>`<div class="table-block"><div class="table-caption">${e(t.title)}<small>${arr(t.rows).length} 行</small></div>${tableHTML(t)}</div>`).join(''):unavailable('本次结果未生成数据表。')}${data.experiment_statistics?`<div class="table-block"><div class="table-caption">实验统计量</div>${kvHTML(data.experiment_statistics)}</div>`:''}</div><div class="tab-pane" id="pane-evidence" role="tabpanel" aria-labelledby="tab-evidence" hidden>${evidenceHTML(data.evidence)}</div><div class="tab-pane" id="pane-trace" role="tabpanel" aria-labelledby="tab-trace" hidden>${data.plan?.length?`<div class="plan-block"><h4>分析计划</h4>${traceHTML(data.plan)}</div>`:''}${traceHTML(data.trace)}</div><div class="tab-pane" id="pane-contract" role="tabpanel" aria-labelledby="tab-contract" hidden>${kvHTML(data.metric_contract||{})}${data.experiment_contract?`<h3 class="subsection-title">实验注册合同</h3>${kvHTML(data.experiment_contract)}`:''}${data.plan&&!Array.isArray(data.plan)?`<h3 class="subsection-title">样本规划与假设</h3>${kvHTML(data.plan)}`:''}</div></section>${arr(data.suggestions).length?`<div class="suggestion-box"><h3>后续检查</h3><ul class="simple-list">${data.suggestions.map(s=>`<li>${e(text(s))}</li>`).join('')}</ul></div>`:''}${arr(data.limitations).length?`<details class="result-limitations"><summary>数据来源与适用范围</summary><ul>${data.limitations.map(l=>`<li>${e(l)}</li>`).join('')}</ul></details>`:''}<div class="report-download-bar"><span>${icon('file')}把结论与证据一起带走</span><div><button type="button" class="text-link" data-download="html">HTML 报告 ↗</button><button type="button" class="text-link" data-download="md">Markdown ↓</button><button type="button" class="text-link" data-download="json">完整 JSON ↓</button></div></div>`;bindResult(data);}
function selectTab(name){document.querySelectorAll('[data-tab]').forEach(b=>{const a=b.dataset.tab===name;b.classList.toggle('active',a);b.setAttribute('aria-selected',String(a));b.tabIndex=a?0:-1;});document.querySelectorAll('.tab-pane').forEach(p=>p.hidden=p.id!==`pane-${name}`);}
function bindResult(data){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));document.querySelector('.result-tabs')?.addEventListener('keydown',ev=>{const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(document.activeElement);if(i<0)return;let n;if(ev.key==='ArrowRight')n=(i+1)%tabs.length;else if(ev.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(ev.key==='Home')n=0;else if(ev.key==='End')n=tabs.length-1;else return;ev.preventDefault();selectTab(tabs[n].dataset.tab);tabs[n].focus();});document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{selectTab('evidence');const detail=document.getElementById(`evidence-${b.dataset.evidence}`);if(detail){detail.open=true;detail.scrollIntoView({behavior:'smooth',block:'start'});}else toast('对应证据未包含在本次结果中。');});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadReport(b.dataset.download,data,b));document.querySelectorAll('.copy-sql').forEach(b=>b.onclick=async()=>{const code=b.closest('.evidence-card').querySelector('pre').textContent;try{await navigator.clipboard.writeText(code);toast('SQL 已复制。');}catch{toast('浏览器未授予复制权限，可在证据区选择 SQL 复制。');}});document.querySelectorAll('[data-clarify]').forEach(b=>b.onclick=()=>{if(!state.online){toast('连接 API 后可补充问题并重新分析。');return;}document.querySelector('#question').value+=`\n补充：${text(data.clarification.options[Number(b.dataset.clarify)])}`;markChanged();document.querySelector('#question').focus();});}
async function downloadReport(format,data,button){button.disabled=true;try{let blob;const {feedback_token,...publicResult}=data;if(format==='json')blob=new Blob([JSON.stringify(publicResult,null,2)],{type:'application/json;charset=utf-8'});else if(state.online&&!data._replay&&data.run_id){const response=await fetch(api(`/api/v1/runs/${encodeURIComponent(data.run_id)}/report?format=${format}`),{headers:state.accessToken?{Authorization:`Bearer ${state.accessToken}`}:{}});if(!response.ok)throw new Error(`报告获取失败（HTTP ${response.status}）`);blob=await response.blob();}else blob=new Blob([format==='html'?reportHTML(data):reportMD(data)],{type:format==='html'?'text/html;charset=utf-8':'text/markdown;charset=utf-8'});const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`${domainID()}-${state.scenario}-${(data.run_id||'snapshot').slice(0,8)}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(href),2000);toast('报告已生成。');}catch(error){toast(error.message);}finally{button.disabled=false;}}
function renderCases(){main.innerHTML=`${heading('CASE STUDIES','从问题到决策的完整案例','业务背景、分析取舍、计算路径与行动验收，以同一条证据链呈现。')}
<nav class="case-jump" aria-label="案例目录"><a href="#case-growth" data-scroll="case-growth">01 留存诊断</a><a href="#case-quality" data-scroll="case-quality">02 数据质量</a><a href="#case-experiment" data-scroll="case-experiment">03 实验评审</a><a href="#case-repurchase" data-scroll="case-repurchase">04 复购计划</a></nav>
<article class="case-study" id="case-growth"><div class="case-study-header"><span class="eyebrow">CASE 01 / GROWTH OPERATIONS COPILOT</span><span class="tag">个人项目 · 合成事件</span></div><div class="case-study-intro"><div><h2>留存下滑时，<br>先找到值得验证的环节。</h2><p>新增用户规模与留存率同时受到获客结构、承接体验和数据出数影响。单一总指标不能回答“先修哪里”。</p></div><dl class="case-facts"><dt>使用者</dt><dd>增长运营 / 产品 / 数据分析</dd><dt>主要结果</dt><dd>成熟注册 cohort 的精确 D7 留存</dd><dt>机制指标</dt><dd>注册后 24h 激活与有序承接漏斗</dd><dt>交付</dt><dd>证据报告 + 可验证的行动方案</dd></dl></div>
<div class="case-body"><div class="case-aside"><span>我的实现</span><h3>让排查顺序<br>成为分析能力的一部分。</h3></div><div><ol class="case-steps"><li><strong>先定义“下降”。</strong><p>对齐注册 cohort、自然日时区、成熟窗口和对比周期。精确 D7 与次 1—7 日回访使用不同指标，未成熟不填 0。</p></li><li><strong>把总变化拆成可解释的部分。</strong><p>按渠道、端和版本检查表现，将结构贡献与组内贡献分开。拆解回答“变化主要发生在哪里”，进一步因果判断交给实验。</p></li><li><strong>沿事件顺序核验承接。</strong><p>在同一注册 cohort 内计算 24 小时有序漏斗，结合版本与发布记录建立候选解释，保存支持证据、反证和下一项验证。</p></li><li><strong>把发现写成行动合同。</strong><p>指定优先问题、要改变的环节、主要结果及体验围栏，明确复查条件，形成可直接讨论的决策备忘录。</p></li></ol></div></div>
<div class="case-output"><div><span class="eyebrow">COMPUTED EVIDENCE</span><div id="case-growth-summary">读取案例计算结果…</div></div><a class="button button-primary" href="#growth?scenario=business_drop">打开完整分析 ${icon('arrow-right')}</a></div></article>
<article class="case-study" id="case-quality"><div class="case-study-header"><span class="eyebrow">CASE 02 / DATA QUALITY</span><span class="tag tag-amber">延迟 → 阻断 → 回填 → 数据恢复</span></div><div class="case-study-intro"><div><h2>看板在报警，<br>经营结论需要先等一等。</h2><p>同一业务问题遇到未到齐的活动事件，回访率可能被低估。回填恢复数据可用性后，本例仍需诊断实际存在的留存下滑。</p></div><div class="case-quality-flow"><div><span>01</span><strong>发现异常</strong><small>批次与水位检查</small></div><div><span>02</span><strong>暂停受影响结论</strong><small>标记指标和日期范围</small></div><div><span>03</span><strong>回填后重算</strong><small>同口径复核与质量告警恢复</small></div></div></div><div class="case-body two-col"><div><h3>怎样避免错判</h3><p>质量检查先于业务解释。批次完整性以已知到数合同为依据，数据不完整时不输出受影响指标的经营判断；报告保留质量状态、数据截至时间和恢复条件。</p></div><div><h3>怎样完成闭环</h3><p>相同规则保存告警指纹、首次和最近观测，重复运行更新状态。回填后执行质量与指标检查，记录状态转移，便于核验“何时发生、何时恢复”。</p></div></div><div class="case-links"><a class="button button-secondary" href="#growth?scenario=late_data">检查延迟场景 ${icon('arrow-right')}</a><a class="button button-secondary" href="#growth?scenario=recovered">查看回填结果 ${icon('arrow-right')}</a><a class="text-link" href="#monitoring">告警与运行记录 ↗</a></div></article>
<article class="case-study" id="case-experiment"><div class="case-study-header"><span class="eyebrow">CASE 03 / EXPERIMENT DECISION</span><span class="tag tag-blue">注册合同 · ITT · 围栏</span></div><div class="case-study-intro"><div><h2>实验结果正向，<br>是否已经具备放量条件？</h2><p>使用独立合成实验数据，评审分流、成熟、效应区间、配置一致性及体验风险。每种状态对应明确动作；实验数值不作为上一个诊断案例的修复收益。</p></div><dl class="case-facts"><dt>估计对象</dt><dd>用户级随机分配的 ITT 效应</dd><dt>主要指标</dt><dd>精确 D7 留存率</dd><dt>先验约束</dt><dd>观察窗口 / 分配比例 / MDE / 围栏</dd><dt>决策形式</dt><dd>修复、等待、继续积累、调整或灰度评审</dd></dl></div><div class="decision-matrix"><div><b>数据无效</b><span>先修分流、结果缺失或配置问题</span></div><div><b>观察未成熟</b><span>等待完整窗口，不把空值当无效</span></div><div><b>有效但不充分</b><span>结合预设 MDE 与区间说明不确定性</span></div><div><b>主要指标与围栏</b><span>效应满足门槛且围栏通过，再进入人工灰度评审</span></div></div><div class="case-output"><div><span class="eyebrow">EIGHT DECISION SCENARIOS</span><p>健康正向、分流异常、围栏恶化、未成熟、证据不足、不等比例、配置变更、结果缺失。</p></div><a class="button button-primary" href="#experiments">进入实验评审 ${icon('arrow-right')}</a></div></article>
<article class="case-study" id="case-repurchase"><div class="case-study-header"><span class="eyebrow">CASE 04 / REPURCHASE OPERATIONS</span><span class="tag">第二业务域 · 合成订单</span></div><div class="case-study-intro"><div><h2>把一份用户分群，<br>变成有预算边界的运营计划。</h2><p>从成熟复购队列确定观察范围，用截至日之前的订单做时点 RFM，形成可核对的候选与留出计划。</p></div><dl class="case-facts"><dt>复购窗口</dt><dd>次 7 日 / 次 30 日完整观察</dd><dt>分群原则</dt><dd>不使用截至日之后的未来订单</dd><dt>计划约束</dt><dd>预算、触达单价、稳定随机留出</dd><dt>验证目标</dt><dd>通过后续随机干预估计实际增量</dd></dl></div><div class="case-body two-col"><div><h3>控制信息时点</h3><p>候选排序与分群只使用决策时点可获得的信息。R、F、M 各自的窗口明确记录，观察期交易额不被称为利润或净 LTV。</p></div><div><h3>保留效果验证的位置</h3><p>候选计划明确处理组与留出组、人数和预计成本。该演示交付方案，实际触达、营销增量及收益需要真实干预数据验证。</p></div></div><div class="case-links"><a class="button button-primary" href="#repurchase">查看运营计划 ${icon('arrow-right')}</a><a class="text-link" href="${SOURCE}/blob/main/docs/repurchase-data.md" target="_blank" rel="noopener">查看数据合同 ↗</a></div></article>
<div class="business-archive"><div><span class="eyebrow">ORIGINAL BUSINESS WORK</span><h3>增长与实验业务基础</h3><p>已有业务分析材料与个人参与说明保留在原版作品集。新项目以独立数据与运行记录呈现 AI 分析工程能力。</p><div class="profile-links"><a href="./resources/business-cases.html" target="_blank" rel="noopener">打开完整案例集 ↗</a><a href="./resources/business-cases.html" download>下载独立 HTML 案例集 ↓</a></div></div><a class="button button-secondary" href="${OLD}" target="_blank" rel="noopener">打开原版作品集 ${icon('arrow-up')}</a></div>`;
document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=ev=>{ev.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:'smooth'});});const v=state.version;snapshot('onboarding').then(data=>{if(v!==state.version)return;document.querySelector('#case-growth-summary').innerHTML=`<p>${e(data.summary||'')}</p><div class="case-mini-kpis">${arr(data.kpis).slice(0,3).map(kpiHTML).join('')}</div>`;}).catch(()=>{if(v===state.version)document.querySelector('#case-growth-summary').innerHTML='<p>完整输出包含指标、查询结果、竞争解释、行动方案和 SQL 证据。</p>';});}
async function renderEvaluation(){main.innerHTML=`${heading('EVALUATION & VERIFICATION','用计算记录验证分析能力','业务断言、模型调用与人工提效分别记录，结果保留适用范围。',`<a class="text-link" href="${SOURCE}/tree/main/evals" target="_blank" rel="noopener">原始评测记录 ${icon('arrow-up')}</a>`)}<div id="evaluation-content">${loading('正在读取实际评测记录')}</div>`;const v=state.version;let payload;try{payload=state.online?await jsonFetch(api('/api/v1/evaluations')):await snapshot('evaluations');}catch{payload={status:'not_run',live_status:'not_run'};}if(v!==state.version)return;const model=evaluationModel(payload),data=model.active,cases=model.cases;const suites=arr(data.suites);const suiteRows=suites.length?suites:typeof data.suites==='object'?Object.entries(data.suites).map(([name,value])=>({name,...value})):[];document.querySelector('#evaluation-content').innerHTML=`${evaluationOverviewHTML(model,SOURCE)}
${suiteRows.length?block('分场景验证记录',tableHTML({rows:suiteRows})):''}${model.metrics.length?block('验证维度与计算方式',tableHTML({rows:model.metrics,columns:['label','passed','total','value','unit','description']})):''}
${section('WHAT IS BEING CHECKED','结果正确，需要通过多层验证')}
<div class="reliability-grid">${[['01','口径与时间','精确留存、滚动回访、24h 激活、成熟窗口和截至日分别验证。'],['02','计算与证据','独立 SQL / Python 对照、不变量、分解和统计区间；结论引用实际工具证据。'],['03','判断与失败','数据阻断、实验 SRM、围栏、配置变化及证据不足分别产生可解释状态。'],['04','运行与使用','只读查询、超时、错误返回、报告导出，以及实际运行耗时和反馈记录。']].map(([n,t,b])=>`<article><span>${n}</span><h3>${t}</h3><p>${b}</p></article>`).join('')}</div>
${cases.length?`<section class="result-section"><div class="result-section-head"><h3>${model.isV2?'V2 逐题结果':'旧域逐题结果'}</h3><label class="eval-filter">显示 <select id="eval-filter"><option value="all">全部样本</option><option value="failed">仅未通过</option><option value="onboarding">新用户场景</option><option value="experiments">实验场景</option><option value="repurchase">复购场景</option></select></label></div><div id="eval-cases">${evalCasesHTML(cases)}</div></section>`:''}
<div class="method-note"><h3>如何解读这些数字</h3><p>已经用于修复的题目作为回归样本。封存任务需要在冻结实现后独立执行；重复调用分别记录每次成功与多次一致性。模型响应完成、报告生成和用户点击反馈，都不能单独证明分析正确。</p>${arr(data.limitations).length?`<details class="result-limitations"><summary>本次评测范围与限制</summary><ul>${data.limitations.map(l=>`<li>${e(l)}</li>`).join('')}</ul></details>`:''}<a class="text-link" href="#monitoring">查看运行与使用数据 ${icon('arrow-right')}</a></div>`;document.querySelector('#eval-filter')?.addEventListener('change',ev=>{const f=ev.target.value;const filtered=cases.filter(c=>f==='all'||(f==='failed'?(c.passed===false||c.status==='failed'):c.domain===f));document.querySelector('#eval-cases').innerHTML=evalCasesHTML(filtered);});}
function evalCasesHTML(cases){if(!cases.length)return unavailable('当前筛选没有样本。');return tableHTML({rows:cases.map(c=>({id:c.id,domain:c.domain,question:c.question,category:c.category,status:c.passed===true?'通过':c.passed===false?'未通过':c.status||'',expected_status:c.expected_status,actual_status:c.actual_status,duration_ms:c.duration_ms})),columns:['id','domain','question','category','status','expected_status','actual_status','duration_ms']},150);}
async function renderMonitoring(){main.innerHTML=`${heading('OPERATIONS & OBSERVABILITY','监控与运行记录','记录批次、告警状态和分析任务，把系统本身也纳入可验证的分析。',`<button class="button button-secondary" type="button" id="refresh-monitoring">${icon('refresh')}刷新记录</button>`)}<div class="monitor-source">${icon('clock')}<span>${state.online?'当前分析服务的运行与告警数据':'保存的批次与运行快照；不是实时数据推送'}</span></div><div id="monitor-content">${loading()}</div>`;document.querySelector('#refresh-monitoring').onclick=()=>{delete state.snapshots.monitoring;delete state.snapshots.usage;renderMonitoring();};const v=state.version;const results=await Promise.allSettled([state.online?jsonFetch(api('/api/v1/monitoring')):snapshot('monitoring'),state.online?jsonFetch(api('/api/v1/usage')):snapshot('usage')]);if(v!==state.version)return;const monitoring=results[0].status==='fulfilled'?results[0].value:null;const usage=results[1].status==='fulfilled'?results[1].value:null;const jobs=arr(monitoring?.jobs),alerts=arr(monitoring?.alerts),transitions=arr(monitoring?.transitions);document.querySelector('#monitor-content').innerHTML=`${section('DATA OPERATIONS','质量监控与告警生命周期','日级批次规则、重复告警与恢复记录。')}${monitoring?`<div class="kpi-grid monitor-kpis">${[{label:'已记录批次',value:jobs.length,unit:'次'},{label:'告警记录',value:alerts.length,unit:'条'},{label:'状态转移',value:transitions.length,unit:'次'}].map(kpiHTML).join('')}</div><div class="monitor-cadence"><span>调度状态</span><strong>${e(statusLabel(monitoring.scheduler_status||'按运行记录'))}</strong><span>${e(text(monitoring.cadence||''))}</span></div>${alerts.length?block('告警清单',tableHTML({rows:alerts,columns:['title','category','status','occurrences','first_seen','last_seen','resolved_at']})):unavailable('当前快照没有告警记录。')}${jobs.length?`<details class="result-section monitor-details" open><summary>批次执行记录 <span>${jobs.length} 次</span></summary>${tableHTML({rows:jobs,columns:['created_at','scenario','status','analysis_status','reused','summary']})}</details>`:''}${transitions.length?`<details class="result-section monitor-details"><summary>状态变化与恢复记录 <span>${transitions.length} 次</span></summary>${tableHTML({rows:transitions,columns:['occurred_at','alert_key','previous_status','status','note']})}</details>`:''}${monitoring.rules?`<details class="result-section monitor-details"><summary>监控规则与范围</summary><div class="result-section-body">${kvHTML(monitoring.rules)}</div></details>`:''}`:unavailable('没有读取到监控记录。运行监控批次后将展示实际状态。')}
${section('PRODUCT ANALYTICS','分析 Agent 自己','区分实际运行、匿名反馈和经过核验的任务成功。')}${usage?usageHTML(usage):unavailable('当前没有可读取的使用记录。')}
<div class="method-note"><h3>从任务失败，反推产品改进</h3><p>问题理解、指标、时间窗口、工具执行、证据解释和交付分别归类。一次运行完成仅说明流程结束，任务成功仍需答案标准或人工核验；真实参与者、满意度和提效结果按实际采集记录呈现。</p><div class="usage-flow"><span>任务提交</span><b>→</b><span>澄清与取数</span><b>→</b><span>报告完成</span><b>→</b><span>人工复核与反馈</span></div></div>`;}
function usageHTML(u){return `<div class="kpi-grid monitor-kpis">${[{label:'实际记录运行',value:u.total_runs??0,unit:'次'},{label:'P50 执行耗时',value:u.latency_ms?.p50,unit:'ms'},{label:'工具失败',value:u.tools?.failures??0,unit:'次'},{label:'人工复核观察',value:u.human_review?.observations??0,unit:'次'}].map(kpiHTML).join('')}</div>${!u.total_runs?'<div class="usage-empty"><div>'+icon('users')+'</div><h3>当前尚无已记录的使用任务</h3><p>连接分析 API 并运行任务后，这里按真实记录汇总。个人试用研究、核验成功率与提效不使用模拟人数替代。</p></div>':''}${arr(u.by_status).length?block('运行方式与完成状态',tableHTML({rows:u.by_status})):''}${arr(u.feedback).length?block('反馈与失败分类',tableHTML({rows:u.feedback})):''}<div class="study-status"><div><span>真实参与者研究</span><strong>${u.study_status==='completed'?'已记录':'未开展'}</strong></div><div><span>核验任务成功率</span><strong>${u.verified_task_success_rate==null?'未记录':e(formatNumber(u.verified_task_success_rate*100))+'%'}</strong></div><div><span>人工平均复核时间</span><strong>${u.human_review?.mean_minutes==null?'未记录':e(formatNumber(u.human_review.mean_minutes))+' 分钟'}</strong></div></div>${studyProtocolHTML({completed:u.study_status==='completed'})}${u.definitions?`<details class="result-limitations"><summary>使用指标定义</summary>${kvHTML(u.definitions)}</details>`:''}${arr(u.limitations).length?`<details class="result-limitations"><summary>数据解释范围</summary><ul>${u.limitations.map(l=>`<li>${e(l)}</li>`).join('')}</ul></details>`:''}`;}
