function feedbackPanel(data){if(data._replay||!state.online||!data.feedback_token||!data.run_id)return '';return `<form id="feedback-form" class="feedback-panel"><div><h3>记录这次分析的使用结果</h3><p>反馈用于区分答案质量、失败原因和人工复核成本。</p></div><div class="feedback-fields"><label>使用结果<select id="feedback-outcome" required><option value="">请选择</option><option value="useful">有帮助</option><option value="needs_revision">需要修改</option><option value="incorrect">结论不正确</option><option value="not_completed">未完成任务</option></select></label><label>主要问题<select id="feedback-category"><option value="none">无问题</option><option value="understanding">问题理解</option><option value="metric">指标口径</option><option value="time_window">时间窗口</option><option value="tool">工具执行</option><option value="evidence">证据解释</option><option value="delivery">交付呈现</option></select></label><label>人工复核分钟数<input id="feedback-minutes" type="number" min="0" max="480" step="0.1" placeholder="选填"></label></div><button type="submit" class="button button-secondary">保存使用反馈</button><span id="feedback-status" role="status"></span></form>`;}
const originalBindResult=bindResult;
bindResult=function(data){originalBindResult(data);const panel=feedbackPanel(data);if(!panel)return;document.querySelector('#analysis-result').insertAdjacentHTML('beforeend',panel);document.querySelector('#feedback-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('button'),status=form.querySelector('#feedback-status');button.disabled=true;const minutes=document.querySelector('#feedback-minutes').value;try{await jsonFetch(api('/api/v1/feedback'),{method:'POST',body:JSON.stringify({run_id:data.run_id,feedback_token:data.feedback_token,outcome:document.querySelector('#feedback-outcome').value,failure_category:document.querySelector('#feedback-category').value,human_minutes:minutes===''?null:Number(minutes)})});status.textContent='已保存，反馈将进入实际使用记录。';form.querySelectorAll('select,input').forEach(el=>el.disabled=true);}catch(err){status.textContent=err.message;button.disabled=false;}};};
function openSettings(){document.querySelector('#api-url').value=state.apiBase;document.querySelector('#api-access-token').value=state.accessToken;document.querySelector('#settings-error').textContent='';document.querySelector('#settings-dialog').showModal();}
document.querySelector('#api-settings').onclick=openSettings;document.querySelector('#close-settings').onclick=()=>document.querySelector('#settings-dialog').close();document.querySelector('#settings-dialog').addEventListener('click',ev=>{if(ev.target===ev.currentTarget){const r=ev.currentTarget.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.currentTarget.close();}});document.querySelector('#settings-form').onsubmit=async ev=>{ev.preventDefault();try{const value=safeBase(document.querySelector('#api-url').value.trim()),token=document.querySelector('#api-access-token').value.trim();if(/^sk-/.test(token))throw new Error('这里填写部署访问令牌。OpenAI API Key 应配置在服务端。');state.apiBase=value;state.accessToken=token;saveBase(value);document.querySelector('#api-access-token').value='';state.controller?.abort();document.querySelector('#settings-dialog').close();await connect();toast(state.online?'已连接分析服务。':'未连接到服务，当前展示保存的计算回放。');}catch(err){document.querySelector('#settings-error').textContent=err.message==='Invalid URL'?'请填写完整的 HTTPS API 地址。':err.message;}};document.querySelector('#reset-settings').onclick=async()=>{state.apiBase='';state.accessToken='';saveBase('');document.querySelector('#api-access-token').value='';document.querySelector('#settings-dialog').close();await connect();};
function closeNav(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#mobile-toggle').setAttribute('aria-expanded','false');document.querySelector('#nav-scrim')?.classList.remove('visible');updateSidebarAccessibility();}
function updateSidebarAccessibility(){const sidebar=document.querySelector('#sidebar'),hidden=innerWidth<=760&&!sidebar.classList.contains('open');sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden));}
document.querySelector('#mobile-toggle').onclick=()=>{const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#mobile-toggle').setAttribute('aria-expanded',String(open));document.querySelector('#nav-scrim')?.classList.toggle('visible',open);updateSidebarAccessibility();};document.querySelector('#nav-scrim')?.addEventListener('click',closeNav);document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeNav();});window.addEventListener('resize',updateSidebarAccessibility);window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});document.querySelector('.skip-link').addEventListener('click',ev=>{ev.preventDefault();main.focus();main.scrollIntoView({block:'start'});});hydrateIcons();render();connect();
